-- script: main
-- velox:lock-timeout 5s

CREATE TYPE "case_status" AS ENUM ('active', 'banned', 'pending');
CREATE TYPE "users_role" AS ENUM ('admin', 'viewer');
CREATE TABLE "orgs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "orgs_id_seq") NOT NULL,
  "name" character varying NOT NULL DEFAULT '',
  CONSTRAINT "orgs_pkey" PRIMARY KEY ("id")
);
-- review: unindexed-fk: foreign key column users.mentor_id has no index that leads with it: With, Has and joins through it, and deletes in users, scan users; declare an index, or -allow unindexed-fk=users.mentor_id; unindexed-fk: foreign key column users.org_id has no index that leads with it: With, Has and joins through it, and deletes in orgs, scan users; declare an index, or -allow unindexed-fk=users.org_id
CREATE TABLE "users" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "users_id_seq") NOT NULL,
  "org_id" bigint NOT NULL DEFAULT 0,
  "name" character varying NOT NULL DEFAULT '',
  "email" character varying(120) NOT NULL DEFAULT '',
  "bio" character varying,
  "role" "users_role" NOT NULL DEFAULT 'viewer',
  "status" "case_status" NOT NULL DEFAULT 'active',
  "logins" integer NOT NULL DEFAULT 0,
  "created_at" timestamp with time zone NOT NULL,
  "mentor_id" bigint,
  CONSTRAINT "users_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "user_mentor" FOREIGN KEY ("mentor_id") REFERENCES "users" ("id") ON DELETE SET NULL,
  CONSTRAINT "users_orgs_users" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id")
);
CREATE INDEX "users_by_name" ON "users" ("name");
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
COMMENT ON COLUMN "users"."name" IS 'the display name';
-- review: unindexed-fk: foreign key column posts.author_id has no index that leads with it: With, Has and joins through it, and deletes in users, scan posts; declare an index, or -allow unindexed-fk=posts.author_id
CREATE TABLE "posts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "posts_id_seq") NOT NULL,
  "author_id" bigint NOT NULL DEFAULT 0,
  "title" character varying(200) NOT NULL DEFAULT '',
  "status" "case_status" NOT NULL DEFAULT 'active',
  CONSTRAINT "posts_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "posts_users_posts" FOREIGN KEY ("author_id") REFERENCES "users" ("id") ON DELETE CASCADE
);
CREATE TABLE "alphas" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "alphas_id_seq") NOT NULL,
  "beta_id" bigint,
  CONSTRAINT "alphas_pkey" PRIMARY KEY ("id")
);
-- review: unindexed-fk: foreign key column beta.alpha_id has no index that leads with it: With, Has and joins through it, and deletes in alphas, scan beta; declare an index, or -allow unindexed-fk=beta.alpha_id
CREATE TABLE "beta" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "beta_id_seq") NOT NULL,
  "alpha_id" bigint,
  CONSTRAINT "beta_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "beta_alphas_alpha" FOREIGN KEY ("alpha_id") REFERENCES "alphas" ("id") ON DELETE SET NULL
);
-- review: unindexed-fk: foreign key column alphas.beta_id has no index that leads with it: With, Has and joins through it, and deletes in beta, scan alphas; declare an index, or -allow unindexed-fk=alphas.beta_id
ALTER TABLE "alphas" ADD CONSTRAINT "alphas_beta_beta" FOREIGN KEY ("beta_id") REFERENCES "beta" ("id") ON DELETE SET NULL;
